import {equipmentBoard,equipmentDetails} from './equipment-view.mjs';
import {EQUIPMENT_SLOTS} from './equipment-data.mjs';
import {equippedEntry,slotFamily} from './inventory-data.mjs';
import {compareItems,itemContribution} from './inventory-engine.mjs';

const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=v=>v.toLocaleString('ko-KR',{maximumFractionDigits:3});
const percent=v=>`${v>0?'+':''}${number(v)}%`;
function badge(result,mode) {
  const value=mode==='contribution'?result.share:result.gain;
  return `<span class="inventory-impact ${result.error?'pending':value<0?'loss':'gain'}" title="${esc(result.error??(mode==='contribution'?'이 장비를 제외한 피해와의 차이 / 현재 피해':'현재 착용 장비 대비 평균 1회 피해 변화'))}">${Number.isFinite(value)?percent(value):result.noBaseline?'기준 장비 필요':'환산 필요'}</span>`;
}
export function inventoryPage(p,{selectedSlot,selectedItemId,filter='slot',sort='recent',mode='compare',snapshot,snapshotError,canUndo=false,calibration=''}) {
  const slot=p.equipment[selectedSlot],current=equippedEntry(p,slot),key=slot.slotKey;
  const results=new Map(),contributions={};
  for(const s of p.equipment){const entry=equippedEntry(p,s);contributions[s.slotKey]=!entry?{empty:true}:snapshot?itemContribution(snapshot,entry.item,p.calibration):{error:snapshotError};}
  for(const entry of p.inventory){
    const target=p.equipment.find(s=>s.slotKey===key&&slotFamily(s.slotKey)===slotFamily(entry.slotKey))??p.equipment.find(s=>s.slotKey===entry.slotKey);
    const worn=equippedEntry(p,target);
    let result=!snapshot?{error:snapshotError}:!worn?{error:'현재 착용 장비를 먼저 지정하세요.',noBaseline:true}:compareItems(snapshot,worn.item,entry.item,p.calibration);
    if(mode==='contribution'&&!result.error)result={...result,...itemContribution(result.afterStats,entry.item,p.calibration)};
    results.set(entry.id,result);
  }
  let entries=p.inventory.filter(entry=>filter==='all'||slotFamily(entry.slotKey)===slotFamily(key));
  if(sort==='gain')entries=[...entries].sort((a,b)=>(results.get(b.id)[mode==='contribution'?'share':'gain']??-Infinity)-(results.get(a.id)[mode==='contribution'?'share':'gain']??-Infinity));
  else if(sort==='level')entries=[...entries].sort((a,b)=>(b.item.level??0)-(a.item.level??0));
  else entries=[...entries].reverse();
  const selected=entries.find(entry=>entry.id===selectedItemId)??entries.find(entry=>entry.id===current?.id)??entries[0];
  const result=selected?results.get(selected.id):null;
  const actualComparison=selected&&snapshot&&current?compareItems(snapshot,current.item,selected.item,p.calibration):null;
  const selectedElsewhere=selected&&p.equipment.some(s=>s.equippedId===selected.id&&s!==slot);
  const details=entry=>entry?`<div data-inventory-detail="${esc(entry.id)}">${equipmentDetails({item:entry.item})}</div>`:'<div class="inventory-empty-detail">착용 중인 장비를 선택한 뒤<br>‘현재 착용 상태 기록’을 누르세요.</div>';
  return `<div class="equipment-workspace inventory-workspace">${equipmentBoard(p,selectedSlot,'miracle',canUndo,{contributions})}<div class="inventory-content"><section class="panel inventory-panel"><div class="section-heading"><div><h2>${filter==='slot'?esc(slot.name)+' 보관함':'전체 장비 보관함'}</h2><p>아이콘 위 숫자는 ${mode==='compare'?'현재 착용 장비와 교체했을 때의 최종 피해 변화':'해당 장비를 착용했을 때의 피해 기여도'}입니다.</p></div><span class="tag">${p.inventory.length} / 300</span></div><p class="inline-note">비교 조건: ${p.stats.target==='boss'?'보스 몬스터':'일반 몬스터'} · ${p.stats.attackType==='skill'?'스킬 공격':'기본 공격'} <a href="#spec" data-goto="spec">조건 변경 ↗</a></p><div class="inventory-toolbar"><div class="segmented"><button data-inventory-filter="slot" class="${filter==='slot'?'selected':''}">선택 부위</button><button data-inventory-filter="all" class="${filter==='all'?'selected':''}">전체</button></div><label class="inventory-sort">정렬<select data-inventory-sort><option value="recent" ${sort==='recent'?'selected':''}>최근 등록</option><option value="gain" ${sort==='gain'?'selected':''}>피해 효율</option><option value="level" ${sort==='level'?'selected':''}>레벨</option></select></label></div><div class="segmented inventory-metric"><button data-inventory-metric="compare" class="${mode==='compare'?'selected':''}">교체 시 피해 차이</button><button data-inventory-metric="contribution" class="${mode==='contribution'?'selected':''}">장착 시 기여도</button></div><div class="inventory-grid">${entries.map(entry=>{
    const worn=p.equipment.some(s=>s.equippedId===entry.id),s=EQUIPMENT_SLOTS.find(s=>s.key===entry.slotKey),item=entry.item;
    return `<button class="inventory-tile ${selected?.id===entry.id?'selected':''}" data-inventory-item="${esc(entry.id)}" aria-pressed="${selected?.id===entry.id}" aria-label="${esc(item.name)} · ${esc(s?.name??entry.slotKey)}"><span class="inventory-tile-meta">${esc(item.quality||item.rarity||'등급 미확인')} <small>${item.level!==null?'Lv.'+item.level:''}</small></span>${badge(results.get(entry.id),mode)}${item.icon?`<img src="${item.icon}" alt="" loading="lazy">`:`<span class="inventory-fallback" aria-hidden="true">${s?.symbol??'◇'}</span>`}${worn?'<span class="inventory-equipped">E</span>':''}<span class="inventory-tile-name">${esc(item.name)}</span><span class="inventory-tile-stars">${Number.isInteger(item.stars)?'★ '+item.stars:'별 미확인'}</span></button>`;
  }).join('')||'<div class="inventory-empty"><b>이 부위의 장비를 모아 보세요.</b><p>같은 부위의 장비를 여러 개 등록하고 바로 비교할 수 있어요.</p><button class="primary" data-import-equipment="inventory">장비 사진 등록</button></div>'}</div><div class="actions inventory-actions"><button data-import-equipment="inventory">＋ 사진으로 추가</button><button data-new-inventory>＋ 직접 등록</button></div><p class="inline-note">평균 1회 피해 기준입니다. 공속·쿨감·생존 능력의 DPM 효과는 포함하지 않습니다. ‘환산 필요’를 누르면 아래에서 필요한 항목을 확인할 수 있어요.</p></section>
  ${selected?`<section class="panel inventory-comparison"><div class="section-heading"><div><h2>${esc(selected.item.name)}</h2><p>${esc(slot.name)} · 현재 착용 장비와 비교</p></div>${badge(result,mode)}</div>${!current?'<div class="tip">기준 장비를 먼저 기록하면 보유 장비마다 교체 효율이 표시됩니다. 현재 스펙에 이미 포함된 장비를 기준으로 지정하세요.</div>':actualComparison?.error?`<div class="error space-top">${esc(actualComparison.error)}</div><a href="#inventory-calibration" class="mini" data-open-inventory-calibration>환산 설정 열기 ↗</a>`:`<div class="gain-strip"><div><small>현재 착용 장비 → 선택 장비</small><p>슬롯 잠재·에디셔널은 그대로 유지합니다.</p></div><strong class="${actualComparison.gain<0?'negative':''}">${percent(actualComparison.gain)}</strong></div>`}<div class="actions inventory-equip-actions"><button class="primary" data-equip-inventory="${esc(selected.id)}" ${!current||actualComparison?.error||current.id===selected.id||selectedElsewhere?'disabled':''}>비교 결과로 교체</button><button data-baseline-inventory="${esc(selected.id)}" ${current?.id===selected.id||selectedElsewhere?'disabled':''}>${current?.id===selected.id?'현재 착용 중':'현재 착용 상태 기록'}</button><button data-edit-inventory="${esc(selected.id)}">수정</button><button class="danger" data-delete-inventory="${esc(selected.id)}" ${p.equipment.some(s=>s.equippedId===selected.id)?'disabled':''}>삭제</button></div>${selectedElsewhere?'<p class="inline-note">다른 슬롯에 착용 중인 장비입니다. 해당 슬롯의 착용 연결을 먼저 해제하세요.</p>':''}${current?'<button class="small" data-clear-equipment-baseline>이 부위 착용 연결 해제 · 현재 합계 유지</button>':''}<p class="inline-note">‘현재 착용 상태 기록’은 게임에서 이미 착용 중인 장비를 연결하며 현재 합계를 유지합니다. ‘비교 결과로 교체’는 계산한 스펙으로 기준을 갱신합니다.</p><div class="inventory-item-pair"><article><h3>현재 착용</h3>${details(current)}</article><article><h3>선택한 장비</h3>${details(selected)}</article></div>${actualComparison?`<details class="inventory-differences" open><summary>주 옵션 · 부 옵션 · 주스탯 · 부스탯 비교</summary><div class="table-scroll"><table><thead><tr><th>옵션</th><th>현재</th><th>선택</th><th>차이</th></tr></thead><tbody>${actualComparison.differences.map(row=>`<tr><td>${esc(row.label)}<br><small>${row.source==='base'?'주 옵션':row.source==='random'?'부 옵션':'분류 확인'}${['str','dex','int','luk','strPercent','dexPercent','intPercent','lukPercent'].includes(row.type)?' · '+(p.calibration.mainAttribute?(row.type.replace('Percent','').toUpperCase()===p.calibration.mainAttribute?'주스탯':'부스탯'):'직업 확인'):row.type==='mainFlat'||row.type==='mainPercent'?' · 주스탯':''}</small></td><td>${number(row.old)}${row.unit}</td><td>${number(row.next)}${row.unit}</td><td class="${row.delta<0?'negative':'positive'}">${row.delta>0?'+':''}${number(row.delta)}${row.unit}</td></tr>`).join('')}</tbody></table></div>${actualComparison.excluded?.length?`<p class="inline-note">피해 모델 외 기록: ${esc(actualComparison.excluded.join(', '))}</p>`:''}</details>`:''}</section>`:''}${calibration}</div></div>`;
}
